-- PTDahl research content. Run only in the new PTDahl database. No personal data.
BEGIN;
CREATE SCHEMA IF NOT EXISTS training_knowledge;
CREATE TABLE IF NOT EXISTS training_knowledge.sources (id text PRIMARY KEY, data jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS training_knowledge.exercises (id text PRIMARY KEY, data jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS training_knowledge.questions (id text PRIMARY KEY, data jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS training_knowledge.rules (id text PRIMARY KEY, data jsonb NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
COMMIT;
