INSERT INTO training_knowledge.sources (id,data) VALUES ('S01','{"id": "S01", "title": "Sundhedsstyrelsen: fysisk aktivitet voksne 18 til 64", "url": "https://www.sst.dk/vidensbase/forebyggelse/anbefalinger-om-fysisk-aktivitet/anbefalinger-om-fysisk-aktivitet-og-stillesiddende-tid/anbefalinger-om-fysisk-aktivitet-og-stillesiddende-tid-for-voksne-18-til-64-aar", "type": "myndighed", "summary": "30 minutters daglig aktivitet og muskelstyrkende aktivitet mindst to gange ugentligt.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S02','{"id": "S02", "title": "WHO: Physical activity", "url": "https://www.who.int/europe/news-room/fact-sheets/item/physical-activity", "type": "myndighed", "summary": "For voksne: 150 til 300 minutters moderat eller 75 til 150 minutters høj intensitet ugentligt; muskelstyrkende aktivitet mindst to dage.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S03','{"id": "S03", "title": "ACSM: Resistance training guidelines 2026", "url": "https://acsm.org/resistance-training-guidelines-update-2026/", "type": "faglig_organisation", "summary": "Tilpas belastning og volumen til mål; hjemmetræning og elastikker kan være effektive. Komplekse metoder er ikke nødvendige for alle.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S04','{"id": "S04", "title": "ACSM position stand 2026: originalartikel, abstract", "url": "https://pubmed.ncbi.nlm.nih.gov/41843416/", "type": "forskningsoversigt", "summary": "Styrke og muskelvækst påvirkes forskelligt af belastning og volumen. Undersøgelsen omhandler raske voksne, ikke individuel genoptræning.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S05','{"id": "S05", "title": "CSEP: Get Active Questionnaire", "url": "https://csep.ca/2021/01/20/pre-screening-for-physical-activity/", "type": "screeningsressource", "summary": "Screening er ét led i vurderingen. Positive svar skal følges op; de betyder ikke automatisk lægekrav for alle.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S06','{"id": "S06", "title": "NHS: Couch to 5K running plan", "url": "https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/couch-to-5k-running-plan/", "type": "offentligt_program", "summary": "Eksempel på gradvis løbeopstart med løb og gang samt hviledage. Slutmålet på siden er 30 minutters løb, ikke en garanti for 5 km.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.sources (id,data) VALUES ('S07','{"id": "S07", "title": "NHS: Strength exercises", "url": "https://www.nhs.uk/live-well/exercise/strength-exercises/", "type": "offentlig_oevelsesvejledning", "summary": "Konkrete hjemmeøvelser og gradvis opbygning.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
