INSERT INTO training_knowledge.sources (id,data) VALUES ('S10','{"id": "S10", "title": "HYROX: officielle regelbøger", "url": "https://hyrox.com/rulebook/", "type": "konkurrenceregler", "summary": "Downloadoversigt identificeret. Direkte hentning var blokeret. Sæsonspecifikke vægte og regler er derfor IKKE verificeret eller importeret.", "checked_at": "2026-11-03", "access_status": "index_only_details_pending", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
