INSERT INTO training_knowledge.sources (id,data) VALUES ('S13','{"id": "S13", "title": "Concept2: SkiErg technique", "url": "https://www.concept2.co.uk/training/skierg-technique", "type": "equipment_manufacturer", "summary": "Producentens tekniske beskrivelse af dobbelt stavtag. Understøtter, at SkiErg omfatter koordineret arbejde fra overkrop, krop og ben. Vores vurdering af andre øvelsers overførsel er fortsat et særskilt trænerforslag.", "checked_at": "2026-11-03", "access_status": "retrieved", "license_status": "link_and_original_summary_only"}'::jsonb) ON CONFLICT (id) DO NOTHING;
