INSERT INTO training_knowledge.rules (id,data) VALUES ('R02','{"id": "R02", "topic": "strength_frequency", "evidence_type": "source_summary", "source_ids": ["S03", "S04"], "statement_da": "Træn de store muskelgrupper regelmæssigt; mindst to ugentlige eksponeringer er et relevant mål for raske voksne.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
