INSERT INTO training_knowledge.rules (id,data) VALUES ('R07','{"id": "R07", "topic": "screening", "evidence_type": "source_summary", "source_ids": ["S05"], "statement_da": "Et positivt screeningssvar kræver relevant opfølgning, ikke automatisk en diagnose eller blanketafvisning.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R08','{"id": "R08", "topic": "approval", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Alle genererede eller ændrede programmer er kladder. Kun eksplicit godkendt version kan publiceres.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R09','{"id": "R09", "topic": "equipment", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Øvelser med manglende udstyr må ikke vælges. Alternativer skal også kontrolleres mod begrænsninger.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R10','{"id": "R10", "topic": "time_budget", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Beregn samlet tid inklusive opvarmning, udførelse, pauser, transport og skift. Afvis en plan der overskrider den aftalte tid.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R11','{"id": "R11", "topic": "missing_answers", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Manglende væsentlige oplysninger og modstridende mål giver status afventer_afklaring.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R12','{"id": "R12", "topic": "pain_text", "evidence_type": "proposed_safety_workflow", "source_ids": ["S05"], "statement_da": "Fritekst og strukturerede helbredssvar skal gennemgås. Ord alene må ikke diagnosticere eller erklære en øvelse sikker.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R13','{"id": "R13", "topic": "load", "evidence_type": "proposed_coaching_policy", "source_ids": [], "statement_da": "Ingen opfundne startkilo ud fra alder eller køn. Brug kendte belastninger, teknikvurdering eller forsigtig kalibrering.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R14','{"id": "R14", "topic": "effort", "evidence_type": "proposed_coaching_policy", "source_ids": [], "statement_da": "Forklar oplevet anstrengelse og gentagelser i reserve på dansk. Værdier fastlægges af træneren for den konkrete person.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R15','{"id": "R15", "topic": "progression", "evidence_type": "proposed_coaching_policy", "source_ids": [], "statement_da": "Øg kun belastning eller mængde når gennemførsel, teknik, anstrengelse og symptomer taler for det. Ingen universel procentstigning.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R16','{"id": "R16", "topic": "age_sex", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Alder og køn er kontekst, ikke automatisk belastningsforskrift. Særlige populationer kræver relevante protokoller.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R17','{"id": "R17", "topic": "hyrox", "evidence_type": "product_constraint", "source_ids": ["S10"], "statement_da": "Gem raceformat, sæson og division. Ingen konkurrencevægte før den aktuelle officielle regelbog er verificeret.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R18','{"id": "R18", "topic": "privacy", "evidence_type": "source_summary", "source_ids": ["S11"], "statement_da": "Helbredsdata holdes adskilt fra den fælles vidensbank. Dokumenter behandlingsgrundlag, adgang, sletning og relevant undtagelse for følsomme data.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R19','{"id": "R19", "topic": "feedback", "evidence_type": "product_constraint", "source_ids": [], "statement_da": "Registrer gennemførsel, faktisk belastning, anstrengelse og symptomer. Forslag til ændringer kræver ny godkendelse.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO training_knowledge.rules (id,data) VALUES ('R20','{"id": "R20", "topic": "safety", "evidence_type": "proposed_safety_workflow", "source_ids": [], "statement_da": "Ved aktuelle alvorlige symptomer må programflowet ikke opfordre til at fortsætte træning. Kliniske stop og henvisningsregler skal valideres særskilt.", "status": "draft_requires_review", "version": 1}'::jsonb) ON CONFLICT (id) DO NOTHING;
